# qx2_unzip :: [(1, 'a'), (2, 'b'), (3, 'c')]
def qx2_unzip(pairs):
    if not pairs:
        return [], []
    a, b = zip(*pairs)
    return list(a), list(b)

if __name__ == '__main__':
    print(qx2_unzip([(1, 'a'), (2, 'b'), (3, 'c')]))

